package dk.jamesbabz.madkursus.outbound.recipetemplate.details;
import java.math.BigDecimal;import java.util.UUID;import jakarta.persistence.*;import lombok.*;import dk.jamesbabz.madkursus.outbound.producttemplate.details.ProductTemplateEntity;import dk.jamesbabz.madkursus.service.models.*;
@Entity @Table(name="recipe_template_process_bindings") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class RecipeTemplateProcessBindingEntity{@Id private UUID id;@ManyToOne(optional=false)@JoinColumn(name="recipe_template_step_id")private RecipeTemplateStepEntity recipeTemplateStep;@Column(name="parameter_key")private String parameterKey;@Column(name="recipe_ingredient_id")private UUID recipeIngredientId;@ManyToOne@JoinColumn(name="product_template_id")private ProductTemplateEntity productTemplate;@ManyToOne@JoinColumn(name="prepared_component_id")private RecipeTemplatePreparedComponentEntity preparedComponent;private BigDecimal quantity;@Enumerated(EnumType.STRING)private RecipeUnit unit;private Integer durationSeconds;private Integer temperatureCelsius;@Enumerated(EnumType.STRING)private HeatLevel heatLevel;@Column(name="number_value")private BigDecimal number;@Column(name="text_value")private String text;void setRecipeTemplateStep(RecipeTemplateStepEntity step){this.recipeTemplateStep=step;}}
